def svg(labels,track=1,prefix='flow'):
 color=COLORS[track-1]
 labels=labels[:3]
 nodes=''.join(f'<g><rect x="{20+i*250}" y="48" width="220" height="88" rx="12" fill="#111827" stroke="{color if i!=1 else "#38bdf8"}" stroke-width="2"/><text x="{130+i*250}" y="98" fill="#e5e7eb" text-anchor="middle" font-size="18" font-weight="600">{E(x)}</text></g>' for i,x in enumerate(labels))
 return f'<div class="diagram"><svg class="w-full h-auto" viewBox="0 0 760 185" role="img" aria-label="{E(" para ".join(labels))}" font-family="Inter,system-ui,sans-serif"><defs><pattern id="{prefix}-grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#64748b" opacity=".25"/></pattern><filter id="{prefix}-glow"><feGaussianBlur stdDeviation="1.8"/></filter></defs><rect width="760" height="185" fill="url(#{prefix}-grid)"/><path d="M240 92h30m220 0h30" stroke="#38bdf8" stroke-width="2"/>{nodes}<text x="380" y="166" fill="#cbd5e1" text-anchor="middle" font-size="12">LAYA / INEMA · fluxo conceitual</text></svg></div>'
