def topic(m,t,n):
 ident=m['id'];track=int(ident[0]);mid=f'modulo-{ident}'
 extras=''
 if n in [1,4]:
  extras=f'<div class="comparison"><div class="yes bg-emerald-900/20"><h3>✓ Aplicar com critério</h3><p>{E(t["answer"])}</p></div><div class="no bg-red-900/20"><h3>✗ Evitar a conclusão automática</h3><p>{E(t["exercise"])}</p><p>Não aceite uma resposta só pelo nome do campo ou pela aparência de precisão. Confira a definição e o contexto desta seção.</p></div></div>'
 if n==2:
  extras='<ol class="timeline">'+''.join(f'<li><span class="circle">{i}</span><div><strong>{name}</strong><p>{E(text)}</p></div></li>' for i,(name,text) in enumerate([('Observe',t['example']),('Defina',t['what'].split('. ')[0]+'.'),('Confira',t['answer'])],1))+'</ol>'
 if n in [3,5]:extras+=f'<aside class="tip bg-primary/10 border-primary/30"><h3>Dica prática</h3><p>{E(t["answer"])}</p></aside>'
 if n==3:extras+=f'<div class="codebox"><h3>{"Comando / esquema de referência" if track in [2,3] else "Exemplo de raciocínio"}</h3><pre><code>{E(CODES[ident])}</code></pre></div>'
 return f'''<section id="topico-{n}" class="topic" data-inema-topic="{mid}#topico-{n}" data-inema-module="{ident}"><div class="topic-heading"><span class="circle">{n}</span><h2 class="text-2xl font-bold">{E(t['title'])}</h2></div><div class="inema-prose"><h3>O que é</h3><p data-inema-block="{mid}-t{n}-what">{E(t['what'])}</p><h3>Por que aprender</h3><p data-inema-block="{mid}-t{n}-why">{E(t['why'])}</p></div><div class="example"><strong>Exemplo aplicado</strong><p data-inema-block="{mid}-t{n}-example">{E(t['example'])}</p></div>{extras}{concept_grid(t)}<div class="exercise"><h3>Teste sua compreensão</h3><p>{E(t['exercise'])}</p><details><summary>Conferir resposta comentada</summary><p>{E(t['answer'])}</p></details></div><div class="toolbar"><button class="justify-start" data-inema-read-toggle aria-pressed="false">Marcar como lido</button><button class="justify-start" data-inema-doubt-toggle aria-pressed="false">Tenho uma dúvida</button></div></section>'''

