 ident=m['id'];track=int(ident[0]);toc='<ol class="toc">'+''.join(f'<li><a href="#topico-{i}">{E(t["title"])}</a></li>' for i,t in enumerate(m['topics'],1))+'</ol>'
 diaglabels={'1-1':['Estado','Decisão','Revisão'],'1-2':['choice','score','noul'],'2-1':['Código + pesos','Modelo residente','Inferência'],'2-2':['Idioma','Checkpoint','Limite de tokens'],'3-1':['Ticket em PT','Quatro sinais','Atendente'],'3-2':['Evento','Política','Executor'],'4-1':['Dados rotulados','Métricas','Conclusão'],'4-2':['Treino','Calibração','Teste reservado']}[ident]
 body=f'<div class="breadcrumb"><a href="../../index.html">Início</a> / <a href="index.html">Trilha {track}</a> / {ident.replace("-",".")}</div><header class="module-hero"><span class="eyebrow">MÓDULO {ident.replace("-",".")}</span><h1>{E(m["title"])}</h1><p class="lead">{E(m["punch"])}</p><div class="stats"><span>6 tópicos</span><span>35–50 min com prática</span><span>{TRACKS[track-1][0]}</span><span>Exercícios comentados</span></div></header>{svg(diaglabels,track,ident)}{meter("modulo:"+ident)}{meter()}{toc}'+''.join(topic(m,t,i) for i,t in enumerate(m['topics'],1))
 nxt=MODULES[index+1] if index+1<len(MODULES) else None
